package com.codecircle.compiler;
import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/compiler") public class CompileController {record Req(String code){} record Res(boolean success,boolean timedOut,String output){}
@PostMapping("/compile") ResponseEntity<?> compile(@RequestBody Req r)throws Exception{if(r.code()==null||r.code().isBlank()||r.code().length()>50000)return ResponseEntity.badRequest().body(Map.of("message","Code must be 1-50000 characters"));if(!r.code().contains("class Main"))return ResponseEntity.badRequest().body(Map.of("message","Use Main as the entry class"));Path d=Files.createTempDirectory("cc-compile-");try{Path f=d.resolve("Main.java");Files.writeString(f,r.code(),StandardCharsets.UTF_8);Process p=new ProcessBuilder("javac","-encoding","UTF-8","-Xlint:none","Main.java").directory(d.toFile()).redirectErrorStream(true).start();boolean done=p.waitFor(5,TimeUnit.SECONDS);if(!done){p.destroyForcibly();return ResponseEntity.ok(new Res(false,true,"Compilation timed out"));}String out=new String(p.getInputStream().readAllBytes(),StandardCharsets.UTF_8);return ResponseEntity.ok(new Res(p.exitValue()==0,false,out.isBlank()?"Compilation successful":out));}finally{try(var s=Files.walk(d)){s.sorted(Comparator.reverseOrder()).forEach(x->{try{Files.deleteIfExists(x);}catch(Exception ignored){}});}}}}
